import{_ as t}from"./chunks/TKDash.lD9YlMS3.js";import{_ as s,o as i,c as a,ao as h}from"./chunks/framework.DKR63sBc.js";const u=JSON.parse('{"title":"TKDash Survey Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"developers/tkdash.md","filePath":"developers/tkdash.md","lastUpdated":null}'),n={name:"developers/tkdash.md"};function o(r,e,l,p,d,c){return i(),a("div",null,[...e[0]||(e[0]=[h('<h1 id="TKDash-Survey-Dashboard" tabindex="-1">TKDash Survey Dashboard <a class="header-anchor" href="#TKDash-Survey-Dashboard" aria-label="Permalink to &quot;TKDash Survey Dashboard {#TKDash-Survey-Dashboard}&quot;">​</a></h1><p>To process a magnetotelluric site with other sites, you must know which sites recorded <strong>at the same time and at the same sampling rate</strong>. You must also know their distances. TKDash scans a survey directory and shows this data for one site at a time:</p><ul><li><p>the <strong>site</strong> in focus;</p></li><li><p>its <strong>base</strong> sites: sites that recorded with it, within a distance that you select (for interstation processing);</p></li><li><p>its <strong>remote</strong> sites: sites that recorded with it, beyond a second, larger distance (for remote-reference processing).</p></li></ul><p><img src="'+t+`" alt=""></p><h2 id="Open-the-dashboard" tabindex="-1">Open the dashboard <a class="header-anchor" href="#Open-the-dashboard" aria-label="Permalink to &quot;Open the dashboard {#Open-the-dashboard}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Tutorial data</p><p>For a survey to try, download the public Metronix tutorial data of BRGM: <a href="https://github.com/BRGM/razorback-tutorial-data" target="_blank" rel="noreferrer">https://github.com/BRGM/razorback-tutorial-data</a>. The data has six sites near Strasbourg that recorded at 128 Hz at the same time. The screenshot on this page uses this data.</p></div><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Timekeepers</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dash </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> run_tkdash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/survey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># blocks until the window closes</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">write_reference_plan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plan.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dash) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the choices made in the window survive the session</span></span></code></pre></div><p>If you do not give a path, <a href="/Timekeepers.jl/previews/PR4/api#Timekeepers.run_tkdash"><code>run_tkdash</code></a> opens a folder dialog. A launcher accepts the survey directory as its argument:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/tkdash.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/survey</span></span></code></pre></div><p>One survey can contain Metronix, LEMI-424 and GEOMAG sites together. The scan reads <strong>only the headers</strong>: the <code>.ats</code> headers of a Metronix site, and the first and the last lines of LEMI-424 and GEOMAG files. Thus, a large survey opens in one or two seconds.</p><ul><li><p>A site is a directory that holds Metronix <code>meas_*</code> directories or LEMI-424 or GEOMAG files.</p></li><li><p>The scan looks four levels deep in directories that are not sites.</p></li><li><p>The scan ignores the rate directories of a site (<code>site002.128</code> next to <code>site002</code>). Thus, it does not count a site two times.</p></li></ul><h2 id="The-window" tabindex="-1">The window <a class="header-anchor" href="#The-window" aria-label="Permalink to &quot;The window {#The-window}&quot;">​</a></h2><p>The window has the layout of the data dashboard of MTGeophysics:</p><ol><li><p>a header;</p></li><li><p>the map;</p></li><li><p>a thin button that collapses the map;</p></li><li><p>the charts.</p></li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">What it does</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>|&lt; · &lt; Prev · site · Next &gt; · &gt;|</strong></td><td style="text-align:left;">Go through the sites, or select one</td></tr><tr><td style="text-align:left;"><strong>Overview</strong></td><td style="text-align:left;">Go back to the full survey, with no site in focus</td></tr><tr><td style="text-align:left;"><strong>Restore</strong></td><td style="text-align:left;">Bring back the sites that you dropped for the site in focus. In the overview, bring back all the dropped sites</td></tr><tr><td style="text-align:left;"><strong>Rate</strong></td><td style="text-align:left;">The menu gives each sampling rate in the survey. Only runs at the selected rate make pairs. <code>All rates</code> makes a pair of two sites that record at the same time, at all rates (for surveys with LEMI, GEOMAG and Metronix sites). The survey opens at 128 Hz if a site recorded at that rate</td></tr><tr><td style="text-align:left;"><strong>Base ≤</strong></td><td style="text-align:left;">Sites that record with the site within this distance (km) are base sites</td></tr><tr><td style="text-align:left;"><strong>Remote ≥</strong></td><td style="text-align:left;">Sites that record with the site at this distance (km) or more are remote sites. Sites between the two distances are neither</td></tr><tr><td style="text-align:left;"><strong>Overlap ≥</strong></td><td style="text-align:left;">Sites that record with the site for less than this time (hours) are neither</td></tr><tr><td style="text-align:left;"><strong>Open…</strong></td><td style="text-align:left;">Scan a different directory</td></tr><tr><td style="text-align:left;"><strong>Export…</strong></td><td style="text-align:left;">Write the base and remote sites of each site as a text table (refer to the subsequent section)</td></tr></tbody></table><p>The site menu shows each site in navy. When the survey is long, the menu scrolls. When you type in the menu, it filters the list.</p><p><strong>Overview.</strong> One chart shows all the runs of all the sites, with one row for each site. The recording hours of each site show at the end of its bar. The runs at other rates are faint. The map shows all the sites.</p><p><strong>A site in focus.</strong> Click a site on the map or a row of a chart, or go to it with the header buttons. Then all the views use that site:</p><ul><li><p>The map shows the site as a <strong>magenta star</strong>, its base sites as <strong>blue</strong> circles and its remote sites as <strong>amber</strong> circles. A circle is darker when its site recorded with the site for a longer time. The other sites stay as small grey dots. A legend gives the names of the markers.</p></li><li><p>The charts become two: <strong>base</strong> (the site above its base sites) and <strong>remote</strong> (the site above its remote sites). The time that each site recorded with the site has the color of that site.</p></li><li><p>At the end of each bar, <code>[1.5h/9.5h]</code> gives the hours that a base or remote site recorded with the site, then its own hours. The row of the site shows <code>[22.4h]</code>.</p></li><li><p>The charts show only the five best base sites and the five best remote sites.</p></li></ul><p><strong>Common window.</strong> A light teal band, with the label <code>common [9.0h]</code>, shows the time when the site and <em>all</em> the base and remote sites that it keeps recorded together. Processing can use this part with all of them at the same time. The band includes all the kept sites, also the sites after the first five. Thus, if you drop a site that recorded only for a short time, the band becomes wider. <a href="/Timekeepers.jl/previews/PR4/api#Timekeepers.common_window"><code>common_window</code></a> calculates the band in code.</p><p><strong>Hover.</strong> Put the pointer on a site on the map or on a row of a chart. A tooltip then shows:</p><ul><li><p>the name of the site;</p></li><li><p>its role and its distance from the site in focus;</p></li><li><p>the hours that it recorded with the site, and its own hours;</p></li><li><p>its channels;</p></li><li><p>on a bar, the file, the rate and the time span of the run.</p></li></ul><p><strong>Electric-only sites.</strong> Base and remote sites give their magnetic field. Thus, only sites that recorded Hx and Hy can be base or remote sites. A telluric site has only electric channels. A telluric site can be the site in focus, and it then uses the magnetic fields of its base and remote sites. Its chart rows show <code>site003 · E only</code>. For LEMI-424 and GEOMAG files, a channel that is zero or blank at the two ends of the file is not a recorded channel.</p><p><strong>Drop a site.</strong> Right-click a base or remote site, on the map or on a chart, to drop it from the lists of the site. For example, drop a site with a defective sensor. A dropped site leaves the comparison:</p><ul><li><p>It goes out of the charts, and the next best site takes its position.</p></li><li><p>It does not make the common window narrower.</p></li><li><p>It is not in the export.</p></li></ul><p>The dropped site stays on the map as a hollow circle. Right-click it there to bring it back. Or push <strong>Restore</strong> to bring back all the sites that you dropped for the site in focus. Each site keeps its own dropped sites.</p><p>The line below the charts tells you what to do, in grey. It shows each drop, scan and export in cyan. It shows each failure in red.</p><p><strong>Zoom.</strong> The map keeps the shape of the survey at true scale. It becomes larger with the window.</p><ul><li><p>Scroll on the map to zoom.</p></li><li><p>Drag a box with the left button to zoom to the box.</p></li><li><p>Drag with the right button to pan.</p></li></ul><p>These functions help when a remote site is far and the base sites are near each other. The zoom stays when you go to a different site. The <strong>Reset Zoom</strong> button below the map shows the full survey again and resets the charts. Scroll on a chart to zoom its time axis. The <code>‹</code> button collapses the map and gives the full width to the charts.</p><h2 id="The-plan-file" tabindex="-1">The plan file <a class="header-anchor" href="#The-plan-file" aria-label="Permalink to &quot;The plan file {#The-plan-file}&quot;">​</a></h2><p><strong>Export…</strong> and <a href="/Timekeepers.jl/previews/PR4/api#Timekeepers.write_reference_plan"><code>write_reference_plan</code></a> write a plain text table. The table has one header line and one row for each site. The columns are aligned:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>site      base                        overlap (h)          remote                                        overlap (h)</span></span>
<span class="line"><span>site002   site004, site006            11.77, 9.00          site099, site100                              11.77, 11.77</span></span>
<span class="line"><span>site004   site009, site002, site006   11.87, 11.77, 9.00   site099, site100                              12.00, 12.00</span></span>
<span class="line"><span>site099   -                           -                    site100, site004, site009, site002, site006   22.98, 12.00, 11.87, 11.77, 9.00</span></span></code></pre></div><p>The base and remote sites are in order of <strong>longest overlap first</strong>. Thus, the first site is the best site. Each <code>overlap (h)</code> column gives the hours of these sites with the site, in the same order. A <code>-</code> shows an empty list. The table holds all the base and remote sites that the site keeps, not only the five that the window shows.</p><p><a href="/Timekeepers.jl/previews/PR4/api#Timekeepers.read_reference_plan"><code>read_reference_plan</code></a> reads the table. It gives one <code>(site, base, base_hours, remote, remote_hours)</code> for each row. Processing steps that make pairs of a site with its base or remote sites can use this data.</p><h2 id="Without-the-window" tabindex="-1">Without the window <a class="header-anchor" href="#Without-the-window" aria-label="Permalink to &quot;Without the window {#Without-the-window}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">survey </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> scan_survey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/survey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">survey[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;site004&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]                                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># one site, its runs and position</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> site_references</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(survey, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;site004&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; rate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, base_km </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, remote_km </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base                                          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># longest overlap first</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">overlap_intervals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(survey[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;site004&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], survey[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;site100&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]; rate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">write_reference_plan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plan.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, survey; rate </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, base_km </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, remote_km </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The scan uses the first line and the last line of a LEMI-424 or GEOMAG file as the start and the end of the recording. Thus, the scan does not see a gap in one file. To show such a gap, cut the record into files at the gap, or examine the record in <a href="./tkapp">TKApp</a>.</p>`,38)])])}const y=s(n,[["render",o]]);export{u as __pageData,y as default};
